
from typing import TypedDict, List


class AgentState(TypedDict):

    # Original user request
    user_query: str

    # AI Career Copilot job results
    job_results: List[dict]

    # Information collected by agents
    research_data: str

    # Analysis generated by Analyzer
    analysis: str

    # Review generated by Critic
    critic_feedback: str

    # Final response generated by Writer
    final_answer: str

    # Track workflow progress
    current_agent: str

    # Track errors
    errors: List[str]

    # Track retry attempts
    retry_count: int

    # Review status
    approved: bool
